{"results": [{"id": "FAM:SF-APPS-015", "label": "Study family SF-APPS-015: Player BEST/AVOID tier tendency in H2 trigger games (55 series)", "score": 0.792, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-015 (0.79)"], "attributes": {"observed_research_question": "Player BEST/AVOID tier tendency in H2 trigger games (55 series)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams and players differ in how often H2 trigger possessions land on the engine's BEST vs AVOID counter.", "observed_result": "Team AVOID% ranges 50.6% (ORL) to 6.8% (SAC); team BEST% 0.0%-15.8%.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No outcome test; player samples 10-178 possessions.", "observed_sample_and_power": "min 10 poss per player", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "trigger_table_clean.csv, 55 series 2022-2026, 179 players, 25 teams, min 10 poss.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-048"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-001"}]}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.757, "reached_via": ["FAM:SF-APPA-005 auto_related_family (record_link_related_to) FAM:SF-APPA-001", "FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-001"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.757, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-005 (0.76)"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.753, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-039 (0.75)"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-070", "label": "Study family SF-APPS-070: H1 usage as predictor of H2 suppression (distribution shift)", "score": 0.751, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-070 (0.75)"], "attributes": {"observed_research_question": "H1 usage as predictor of H2 suppression (distribution shift)", "auto_outcome_status": "rejected", "observed_hypothesis": "First-half reliance on a play type predicts second-half suppression after controlling for H1 PPP / mean reversion.", "observed_result": "Test B: all BH-adjusted null/WEAK (PNR ATT=+0.0313 BH_p=0.0658 WEAK; others NULL). Test C top-1 acc=0.550 vs mean-reversion baseline 0.511 (+0.039) vs most-used 0.239. Test A PULL_UP slope -0.0581 p=0.0030; CUT -0.0917 p [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Matched ATT does not survive BH; predictive lift over mean reversion is only +0.039 (0.550 vs 0.511). Bulk of H2 suppression is RTM.", "observed_sample_and_power": "n=8873 team-games; Test C test n=1008"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:RTM_SELECTION"}]}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.472, "reached_via": ["request matches RQC:RQC-072 (0.75); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-072"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-092", "label": "Study family SF-APPS-092: HasConn share vs pace (possessions per 48)", "score": 0.458, "reached_via": ["request matches RQC:RQC-119 (0.73); FAM:SF-APPS-092 auto_addresses_question RQC:RQC-119"], "attributes": {"observed_research_question": "HasConn share vs pace (possessions per 48)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Connector presence slows pace (substituting half-court organization for transition).", "observed_result": "beta(HasConn share -> poss/48)=-0.86 SE=0.38 t=-2.25 p=0.0266; within-ts corr=-0.002 p=0.782. Mix: TRANSITION -0.448 pp p=0.0013; PNR +0.980 p=0.00187; CUT +1.353 p=1.2e-11; DRIVE -0.542 p=0.0206; SPOT_UP -1.248 p=0.0003 [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Pace beta p=0.0266 but within-ts correlation is 0; no stint clock so poss/48 is period-implied. Mix shifts are clearer than efficiency.", "observed_sample_and_power": "n=28569 periods; mix n_ts=73", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-087"}]}, {"id": "FAM:SF-APPA-048", "label": "Study family SF-APPA-048: Player-level BEST vs AVOID H2 PPP gaps (exploratory)", "score": 0.396, "reached_via": ["FAM:SF-APPS-015 auto_related_family (repeat_order_unknown) FAM:SF-APPA-048"], "attributes": {"observed_research_question": "Player-level BEST vs AVOID H2 PPP gaps (exploratory)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Players score more on BEST-ranked counters than AVOID-ranked counters in the 55-series playsheets.", "observed_result": "78 players with >=5 BEST and >=5 AVOID rows. Top gaps D. Lively II +1.833 (n=6/6), M. Brogdon +1.831 (7/11); some reverse (N. Jokic -0.333 n=8/18; L. Doncic -0.190 n=6/14). Stars mixed (D. White +0.864 n=49/42; SGA +0.33 [cut; read_family for the full text]", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "n is small for most players (single-game playsheets); no multiplicity or clustered test.", "observed_sample_and_power": "78 players; min 5 rows/tier", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-036"}]}, {"id": "FAM:SF-APPS-036", "label": "Study family SF-APPS-036: Player-level BEST vs AVOID PPP gap (initiators, 55-series)", "score": 0.396, "reached_via": ["FAM:SF-APPS-015 auto_related_family (record_link_related_to) FAM:SF-APPS-036"], "attributes": {"observed_research_question": "Player-level BEST vs AVOID PPP gap (initiators, 55-series)", "auto_outcome_status": "supported", "observed_hypothesis": "The team-level BEST vs AVOID gap holds when H2 possessions are filtered to initiating player.", "observed_result": "Mean gap (n>=10 each tier) +0.427 PPP. Mean BEST 1.347 (38 players) vs AVOID 0.920 (94 players). Stars mean gap +0.542 (n=15) vs role +0.428 (n=16). Only 3 players clear n>=30 both tiers (all BOS: White +0.864, Brown +0. [cut; read_family for the full text]", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Pooled player gap +0.427 in the same direction as the team gap; most star cells are below the n>=30 gate.", "observed_sample_and_power": "38/94 players at n>=15; only 3 at n>=30 both tiers", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-030", "label": "Study family SF-APPA-030: Play-type label backfill verification", "score": 0.379, "reached_via": ["FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-030"], "attributes": {"observed_research_question": "Play-type label backfill verification", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Backfilled play-type labels match expected league distributions and team identities.", "observed_result": "PNR 28.7% FAIL (band 20-28%); PULL_UP 7.9% FAIL; 3100 games with team PNR >33% FAIL; PNR PPP 0.948 PASS; temporal PASS; team identity FAIL; 2024-25 PULL_UP ~0-1% for many teams. Final: FAIL.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "2024-25 PULL_UP shares 0.0-2.0% for many teams; 82.8% of PNR labels proxy_calibrated.", "observed_sample_and_power": "921,514 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-001"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}]}], "n_results": 10}

